/**
 * Tests for no-hardcoded-credentials
 * CWE-798 — Detect hardcoded credentials in pg Client or Pool initialization.
 *
 * Generated by: node scripts/generate-rule-tests.mjs
 * Standard: Engineering Standards §5 (side-by-side), §6 (≥5 valid + ≥5 invalid), §8 (RuleTester at describe level)
 */
import { RuleTester } from '@typescript-eslint/rule-tester';
import { describe, it, afterAll } from 'vitest';
import parser from '@typescript-eslint/parser';
import { noHardcodedCredentials } from './index';

/**
 * Every fixture imports a PostgreSQL client, because the rule now abstains in
 * files that use no PostgreSQL at all. Wrapping the arrays rather than editing
 * each fixture means one cannot be left behind — a fixture missing the import
 * would pass vacuously on the gate instead of exercising the detection it was
 * written for.
 */
const withPg = (code: string): string => `import { Pool } from 'pg';\n${code}`;
const pg = <T,>(cases: T[]): T[] =>
  cases.map((c) =>
    typeof c === 'string'
      ? (withPg(c) as T)
      : ({ ...c, code: withPg((c as { code: string }).code) } as T),
  );


RuleTester.afterAll = afterAll;
RuleTester.it = it;
RuleTester.itOnly = it.only;
RuleTester.describe = describe;

const ruleTester = new RuleTester({
  languageOptions: {
    parser,
    ecmaVersion: 2022,
    sourceType: 'module',
    parserOptions: { ecmaFeatures: { jsx: true } },
  },
});

describe('no-hardcoded-credentials', () => {
  describe('Valid Code', () => {
    ruleTester.run('valid - safe patterns', noHardcodedCredentials, {
      valid: pg([
        // Unrelated code should not trigger
        {
          name: 'pg is imported but nothing queries',
          code: `const x = 1;`,
        },
        // Array operations are safe
        {
          code: `const arr = [1, 2, 3];`,
        },
        // Static property values are safe
        {
          code: `const config = { key: "static-value" };`,
        },
        // Properly configured connection
        {
          code: `mongoose.connect(uri, { tls: true });`,
        },
        // Environment variable usage is safe (padding case 5)
        {
          code: `const safe4 = process.env.DB_HOST;`,
        },
      ]),
      invalid: [],
    });
  });

  describe('Invalid Code', () => {
    ruleTester.run('invalid - dangerous patterns', noHardcodedCredentials, {
      valid: [],
      invalid: pg([
        // Triggers noHardcodedCredentials.
        //
        // `Client` used to be unimported here and this still passed, because
        // the rule matched the SPELLING of the callee.
        {
          name: 'a database password literal in the client options',
          code: `import { Client } from 'pg';\nnew Client({ host: 'localhost', password: 'secret123' })`,
          errors: [{ messageId: 'noHardcodedCredentials' }],
        },
      ]),
    });
  });

  /**
   * Regression locks for the defects
   * `benchmarks/rule-corpus/postgresql-security__no-hardcoded-credentials`
   * proved. Each `invalid` case was SILENT on the shipped rule; each `valid`
   * case was REPORTED by it.
   */
  describe('corpus regressions', () => {
    ruleTester.run('the callee is resolved, not spelled', noHardcodedCredentials, {
      valid: pg([
        // FP — a test double named `Client`. There is no database within reach,
        // and this was a CRITICAL hardcoded-credential finding.
        "import { Client } from '../test/fake-transport';\nnew Client({ password: 'not-a-database' });",
        "import Stripe from 'stripe';\nnew Stripe({ password: 'sk_test_x' });",
        'new Client({ password: "unimported" });',
        'class LocalPool {}\nnew LocalPool({ password: "local" });',
      ]),
      invalid: [
        // FN — the namespace spelling. The callee is a MemberExpression with no
        // `.name`, so the rule never looked at it.
        {
          code: "const pg = require('pg');\nnew pg.Pool({ password: 'hunter2-admin' });",
          errors: [{ messageId: 'noHardcodedCredentials' }],
        },
        {
          code: "import pg from 'pg';\nnew pg.Client({ password: 'hunter2' });",
          errors: [{ messageId: 'noHardcodedCredentials' }],
        },
        // A scoped package: the root is `@vercel/postgres`, not `@vercel`.
        {
          code: "import { Pool } from '@vercel/postgres';\nnew Pool({ password: 'v3rc3l' });",
          errors: [{ messageId: 'noHardcodedCredentials' }],
        },
        // The module itself is the constructor.
        {
          code: "const Pool = require('pg-pool');\nnew Pool({ password: 'p' });",
          errors: [{ messageId: 'noHardcodedCredentials' }],
        },
      ],
    });

    ruleTester.run('a DSN is only a credential when it carries one', noHardcodedCredentials, {
      valid: pg([
        // FP — a host and a database and nothing else. Peer, IAM or
        // certificate authentication supplies the secret at connect time.
        // This fired on almost every repository's development defaults.
        "new Pool({ connectionString: 'postgres://db.internal:5432/orders' });",
        "new Pool({ connectionString: 'postgres://postgres@localhost:5432/app_development' });",
        // A username with an EMPTY password is not a secret either.
        "new Pool({ connectionString: 'postgres://app:@db.internal/orders' });",
        // A deploy-time placeholder, not a secret.
        "new Pool({ connectionString: 'postgres://app@${PGHOST}:5432/orders' });",
        // Too malformed to parse discloses nothing this rule can name: an
        // unterminated IPv6 host and a non-numeric port both throw.
        "new Pool({ connectionString: 'postgres://[::1' });",
        "new Pool({ connectionString: 'postgres://h:port/db' });",
        // Not a PostgreSQL protocol at all.
        "new Pool({ connectionString: 'mysql://app:pw@h/db' });",
        // Assembled at runtime from the environment.
        'const dsn = `postgres://${process.env.PGUSER}:${process.env.PGPASSWORD}@h/app`;\nnew Pool({ connectionString: dsn });',
        'new Pool({ connectionString: process.env.DATABASE_URL });',
      ]),
      invalid: pg([
        {
          code: "new Pool({ connectionString: 'postgres://app:p4ssw0rd@db.internal:5432/orders' });",
          errors: [{ messageId: 'noHardcodedCredentials' }],
        },
        // Through one binding hop.
        {
          code: "const DSN = 'postgresql://app:p4ssw0rd@h/db';\nnew Pool({ connectionString: DSN });",
          errors: [{ messageId: 'noHardcodedCredentials' }],
        },
      ]),
    });

    ruleTester.run('the password is folded, and emptiness is not a secret', noHardcodedCredentials, {
      valid: pg([
        // FP — `password: ''` is how a unix-socket or trust-authentication
        // setup is written. It discloses nothing, and it was CRITICAL.
        "new Pool({ host: '/var/run/postgresql', user: 'postgres', password: '' });",
        'new Pool({ password: null });',
        'new Pool({ password: undefined });',
        // The value is not in this file.
        'new Pool({ password: readConfig().databasePassword });',
        'new Pool({ password: process.env.PGPASSWORD });',
        'new Pool({ password: await getSecret("prod/db") });',
        // No `password` key at all.
        "new Pool({ user: 'postgres', database: 'mydb' });",
        // A `password` key on something that is not a connection config.
        "new Pool({ connectionString: process.env.DATABASE_URL });\nexport const seed = { password: 'demo-fixture' };",
        // Written twice — what reaches the constructor is not knowable.
        "let config = { password: 'dev-only' };\nconfig = production;\nnew Pool(config);",
        // No arguments, and a non-object non-string argument.
        { name: 'a pool with no config carries no credential', code: 'new Pool();' },
        'new Pool(loadConfig());',
        // A computed key that is not a static string names nothing knowable.
        "new Pool({ [KEY]: 'secret' });",
        // More binding hops than the walker follows. The bound moved from 4
        // to 8 when value following went multi-hop and cross-file (FP/FN
        // zero-deferral, 2026-10); the chain is ten aliases so the bound,
        // not the chain length, is what this case still pins.
        "const a0 = { password: 'p' };\nconst a1 = a0;\nconst a2 = a1;\nconst a3 = a2;\nconst a4 = a3;\nconst a5 = a4;\nconst a6 = a5;\nconst a7 = a6;\nconst a8 = a7;\nconst a9 = a8;\nconst a10 = a9;\nnew Pool(a10);",
        // Declared without an initialiser, then assigned once: there is a
        // declaration to find but nothing on it to follow.
        'let config;\nconfig = loadConfig();\nnew Pool(config);',
        // A PARAMETER assigned once inside the body — written exactly once,
        // but its definition is not a declaration and carries no initialiser.
        "export function make(config) { config = { password: 'p' }; return new Pool(config); }",
      ]),
      invalid: pg([
        // FN — hoisting the secret into a named constant reads as MORE
        // careful, and turned the finding off.
        {
          code: "const DB_PASSWORD = 'sup3r-s3cret';\nnew Pool({ user: 'app', password: DB_PASSWORD });",
          errors: [{ messageId: 'noHardcodedCredentials' }],
        },
        // FN — the config declared one binding above the constructor, which is
        // how every real application writes it.
        {
          code: "const config = { password: 'fallback-dev-password' };\nnew Pool(config);",
          errors: [{ messageId: 'noHardcodedCredentials' }],
        },
        // ES6 shorthand.
        {
          code: "const password = 'sh0rthand';\nnew Pool({ user: 'app', password });",
          errors: [{ messageId: 'noHardcodedCredentials' }],
        },
        // A computed key names the same property.
        {
          code: "new Pool({ ['password']: 'br4cket-3vasion' });",
          errors: [{ messageId: 'noHardcodedCredentials' }],
        },
        // A TypeScript `satisfies` clause is erased and hides nothing.
        {
          code: "const config = { password: 'm3trics' } satisfies PoolConfig;\nnew Pool(config);",
          errors: [{ messageId: 'noHardcodedCredentials' }],
        },
        // Both spellings in one config are two distinct disclosures.
        {
          code: "new Pool({ connectionString: 'postgres://a:b@h/d', password: 'c' });",
          errors: [
            { messageId: 'noHardcodedCredentials' },
            { messageId: 'noHardcodedCredentials' },
          ],
        },
      ]),
    });

    // NOT wrapped — a file with no PostgreSQL client does no work at all.
    ruleTester.run('the module gate still abstains', noHardcodedCredentials, {
      valid: ["import { Client } from 'some-other-db';\nnew Client({ password: 'x' });"],
      invalid: [],
    });
  });
});

/** FP/FN review 2026-10 (benchmarks/audits/2026-10-10-fp-fn-postgresql-security.md). */
describe('no-hardcoded-credentials — fp/fn review 2026-10', () => {
  ruleTester.run('CRED-1: a DSN with a password anywhere in the file', noHardcodedCredentials, {
    valid: [
      // Local development / test containers.
      { name: 'a loopback test-container DSN is a throwaway default', code: "export const DATABASE_URL = 'postgres://postgres:postgres@localhost:5432/app_test';" },
      { name: 'a 127.0.0.1 DSN is a local default', code: "export const DATABASE_URL = 'postgresql://u:p@127.0.0.1/app';" },
      { name: 'an IPv6 loopback DSN is a local default', code: "export const DATABASE_URL = 'postgres://u:p@[::1]:5432/app';" },
      // No password, or not a DSN.
      { name: 'a DSN with no password carries no secret', code: "export const DATABASE_URL = 'postgres://app@db.internal:5432/orders';" },
      { name: 'a non-postgres URL is not a DSN', code: "export const DOCS = 'see https://u:p@example.com';" },
      { name: 'an unparseable DSN discloses nothing nameable', code: "export const BROKEN = 'postgres://[::1';" },
      { name: 'a DSN assembled from interpolated values is not hardcoded', code: 'export const DSN = `postgres://${user}:${pass}@db.example.com/app`;' },
    ],
    invalid: [
      {
        name: 'a config module holding the production DSN',
        code: "export const DATABASE_URL = 'postgres://admin:Pr0dS3cret!@db.internal.example.com:5432/app';",
        errors: [{ messageId: 'noHardcodedCredentials' }],
      },
      {
        name: 'a knex-style config object with a DSN',
        code: "export default { client: 'pg', connection: 'postgresql://app:hunter2@10.0.0.5:5432/app' };",
        errors: [{ messageId: 'noHardcodedCredentials' }],
      },
      {
        name: 'a template literal without interpolation',
        code: 'export const DATABASE_URL = `postgres://admin:Pr0dS3cret@db.example.com/app`;',
        errors: [{ messageId: 'noHardcodedCredentials' }],
      },
    ],
  });

  ruleTester.run('CRED-2: postgres.js and pg-promise factories', noHardcodedCredentials, {
    valid: [
      { name: 'postgres.js password from the environment is not hardcoded', code: "import postgres from 'postgres';\nexport const sql = postgres({ host: 'db.example.com', password: process.env.PGPASSWORD });" },
      { name: 'a pg-promise DSN from the environment is not hardcoded', code: "import pgPromise from 'pg-promise';\nexport const db = pgPromise()(process.env.DATABASE_URL);" },
    ],
    invalid: [
      {
        name: 'postgres.js DSN',
        code: "import postgres from 'postgres';\nexport const sql = postgres('postgres://admin:Pr0dS3cret@db.example.com:5432/app');",
        errors: [{ messageId: 'noHardcodedCredentials' }],
      },
      {
        name: 'postgres.js options object',
        code: "import postgres from 'postgres';\nexport const sql = postgres({ host: 'db.example.com', username: 'admin', password: 'Pr0dS3cret' });",
        errors: [{ messageId: 'noHardcodedCredentials' }],
      },
      {
        name: 'pg-promise options object',
        code: "import pgPromise from 'pg-promise';\nexport const db = pgPromise()({ host: 'db.example.com', user: 'admin', password: 'Pr0dS3cret' });",
        errors: [{ messageId: 'noHardcodedCredentials' }],
      },
    ],
  });
});
